from packaging.version import Version


def create_version(version_string: str) -> str:
    """Parse and create a Version object from a version string for comparison and manipulation. version_string: A string representation of a version conforming to PEP 440, e.g. '1.0a5' -> '<Version('1.0a5')>'."""
    try:
        version = Version(version_string)
        return str(version)
    except Exception as e:
        raise ValueError(f"Invalid version string '{version_string}': {str(e)}")

from packaging.specifiers import SpecifierSet
from packaging.ranges import VersionRange


def specifier_set_to_range(specifiers: str) -> str:
    """Convert a SpecifierSet into a VersionRange string representation. specifiers: A string representation of version specifiers, e.g. '>=1.0,<2.0' -> '[1.0, 2.0.dev0)'."""
    try:
        specifier_set = SpecifierSet(specifiers)
        version_range = specifier_set.to_range()
        return str(version_range)
    except Exception as e:
        raise ValueError(f"Invalid specifiers: {specifiers!r}") from e

from packaging.specifiers import SpecifierSet


def specifier_set_contains_version(specifier_set: str, version: str, prereleases: bool | None = None) -> bool:
    """Check if a specific version is contained within this SpecifierSet. specifier_set: A string representation of the specifier set (e.g., '>=1.0.0,!=1.0.1'), version: The version string to check for containment in the specifier set, prereleases: Whether or not to match prereleases with this SpecifierSet. If set to None (the default), it will follow the recommendation from PEP 440."""
    try:
        spec_set = SpecifierSet(specifier_set)
        return spec_set.contains(version, prereleases)
    except Exception as e:
        raise ValueError(f"Error processing specifier set '{specifier_set}' with version '{version}': {str(e)}")

from packaging.ranges import VersionRange


def create_empty_version_range(prereleases: bool | None = None) -> dict[str, bool | None]:
    """Return a VersionRange that contains no versions. prereleases: whether pre-release versions should be considered."""
    try:
        result = VersionRange.empty(prereleases=prereleases)
        return {"is_empty": result.is_empty, "prereleases": prereleases}
    except Exception as e:
        raise ValueError(f"failed to create empty version range: {str(e)}")

from packaging.ranges import VersionRange
from packaging.version import Version


def create_singleton_version_range(version: str, prereleases: bool | None = None) -> str:
    """Create a VersionRange that contains only a single specific version. version: A PEP 440 compliant version string or Version object, e.g. '1.0' -> VersionRange singleton for 1.0. prereleases: Whether to include pre-release versions; if None, uses the default behavior."""
    try:
        range_obj = VersionRange.singleton(version, prereleases=prereleases)
        return str(range_obj)
    except Exception as e:
        if "InvalidVersion" in str(type(e)):
            raise ValueError(f"Invalid version format: {version!r}") from e
        raise ValueError(f"Failed to create version range: {str(e)}") from e

from packaging.ranges import VersionRange
from packaging.specifiers import SpecifierSet


def range_contains_version(specifier_set: str, version: str) -> bool:
    """Check if a specific version is contained within this VersionRange. specifier_set: A specifier set that can be converted to a VersionRange using .to_range(). version: The version string to check for containment in the range. >>> range_contains_version('>=1.0,<2.0', '1.5') True >>> range_contains_version('>=1.0,<2.0', '2.0') False """
    try:
        range_obj = SpecifierSet(specifier_set).to_range()
        return range_obj.contains(version)
    except Exception as e:
        raise ValueError(f"Invalid specifier set or version: {e}")

from packaging.ranges import VersionRange
from packaging.specifiers import SpecifierSet


def is_version_range_empty(range_string: str, prereleases: bool = False) -> bool:
    """Check if a VersionRange contains no versions at all. range_string: A string representation of a version range, e.g., '>=1.0,<2.0' -> True. prereleases: Whether pre-releases are allowed in the range."""
    try:
        version_range = VersionRange(range_string, prereleases=prereleases)
        return version_range.is_empty
    except Exception:
        # Try the fallback approach
        try:
            spec_set = SpecifierSet(range_string)
            result = spec_set.is_unsatisfiable
            # Ensure we return a plain boolean, not a bound method
            if callable(result):
                return result()
            return result
        except Exception:
            raise ValueError(f"Invalid version range: {range_string!r}")

