from packaging.specifiers import SpecifierSet


def is_version_range_subset(range1: str, range2: str) -> bool:
    """Check if every version in range1 is also in range2. range1: A version range specifier string, e.g. '>=1.5,<1.8' -> True. range2: Another version range specifier string to check if range1 is a subset of this."""
    try:
        version_range1 = SpecifierSet(range1).to_range()
        version_range2 = SpecifierSet(range2).to_range()
        return version_range1.is_subset(version_range2)
    except Exception as e:
        raise ValueError(f"invalid version range: {str(e)}")

