def is_version_range_superset(range1: str, range2: str) -> bool:
    """Check if every version in another range is also in this range. range1: A version range specifier string, e.g. '>=1.0,<2.0'. range2: Another version range specifier string to check if it's a subset of range1. Example: is_version_range_superset('>=1.0,<2.0', '>=1.5,<1.8') -> True."""
    try:
        version_range1 = SpecifierSet(range1).to_range()
        version_range2 = SpecifierSet(range2).to_range()
        return version_range1.is_superset(version_range2)
    except Exception as e:
        raise ValueError(f"invalid version range: {str(e)}")

