from packaging.version import Version


def get_version_local(version: str) -> str | None:
    """Get the local version segment of a Version object. version: A version string to parse and extract the local version segment from

    >>> print(Version("1.2.3").local)
    None
    >>> Version("1.2.3+abc").local
    'abc'
    """
    try:
        v = Version(version)
        if v._local:
            return ".".join(str(x) for x in v._local)
        else:
            return None
    except Exception as e:
        raise ValueError(f"not a valid version string: {version!r}") from e

