from packaging.utils import canonicalize_version


def canonicalize_version_string(version: str, strip_trailing_zero: bool = True) -> str:
    """Return a canonical form of a version string. version: A version string to canonicalize, e.g. '1.0.0' -> '1'. strip_trailing_zero: Whether to strip trailing zeros from the release segment, e.g. '1.0.0' with strip_trailing_zero=False -> '1.0.0'."""
