from packaging.markers import Marker as _Marker, InvalidMarker


def create_marker(marker: str) -> str:
    """Create a Marker object from a dependency marker expression string. marker: The string representation of a marker expression, e.g. 'python_version >= "3.6"' -> "<Marker('python_version >= \"3.6\"')>"."""
